/**
 * @summary Upload an image file (PNG, JPG, SVG)
 */
export const getUploadImageUrl = () => {
  return `/api/uploads`;
};

export const uploadImage = async (
  uploadImageBody: UploadImageBody,
  options?: RequestInit,
): Promise<UploadedImage> => {
  const formData = new FormData();
  formData.append(`file`, uploadImageBody.file);
  if (uploadImageBody.trimTransparency !== undefined) {
    formData.append(
      `trimTransparency`,
      uploadImageBody.trimTransparency.toString(),
    );
  }
  if (uploadImageBody.removeSemiTransparency !== undefined) {
    formData.append(
      `removeSemiTransparency`,
      uploadImageBody.removeSemiTransparency.toString(),
    );
  }

  return customFetch<UploadedImage>(getUploadImageUrl(), {
    ...options,
    method: "POST",
    body: formData,
  });
};

